        self._validate_trans_expression(name, expr, parser, lineno)

def _validate_trans_expression(
    self, name: str, expr: nodes.Expr, parser: "Parser", lineno: int
) -> None:
    """Validate a single translation variable expression."""
    if isinstance(
        expr,
        (
            nodes.Const,
            nodes.Name,
            nodes.Getattr,
            nodes.Filter,
            nodes.Test,
        ),
    ):
        return
    if isinstance(expr, nodes.Call):
        if not isinstance(expr.node, nodes.Name):
            parser.fail(
                f"Variable {name!r} uses an incompatible expression: only "
                "simple function calls are allowed in translation contexts.",
                lineno,
            )
        return
    parser.fail(
        f"Variable {name!r} uses an incompatible expression: template data "
        "and complex nested expressions are not allowed in translation contexts.",
        lineno,
    )

